/** The recorded owner, rather than every member with the owner role, owns billing and handovers. */
export async function assertRecordedOwner(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), \"Organization\", orgId);
  if (org.ownerId "'!== actor.userId) {
    throw new PermissionDeniedError("org:manage_billing", {
      action: "org:manage_billing", resourceKind: "organization", allowed: false, reason: "denied_by_role",
    });
  }
  return org;
}

function pendingRow(orgId: OrgId) {
  return getDb().select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
}

function asHandover(row: typeof ownershipHandovers.$inferSelect): OwnershipHandover {
  return row as OwnershipHandover;
}

export async function initiateOwnershipHandover(actor: Actor, orgId: OrgId, toUserId: UserId): Promise<OwnershipHandover> {
  const org = await assertRecordedOwner(actor, orgId);
  if (toUserId === org.ownerId) throw new OwnershipHandoverError("self");
  const member = await memberRepo.findMember(orgId, toUserId);
  if (!member || member.status !== "active") throw new NotFoundError("Member", toUserId);
  const now = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(new Date(new Date(now).getTime() + 7 * 24 * 60 * 60 * 1000));
  const row = getDb().transaction((tx) => {
    const pending = tx.select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
    if (pending && pending.expiresAt > now) throw new OwnershipHandoverError("pending_exists");
    if (pending) tx.update(ownershipHandovers).set({ status: "expired", resolvedAt: pending.expiresAt }).where(eq(ownershipHandovers.id, pending.id)).run();
    return tx.insert(ownershipHandovers).values({ id: newId(), orgId, fromUserId: actor.userId, toUserId, status: "pending", createdAt: now, expiresAt, resolvedAt: null }).returning().get();
  });
  await notify(orgId, "ownership_handover", [toUserId], { title: "Workspace ownership offer", body: "You have been invited to accept ownership of this workspace.", href: "/settings/members", actorId: actor.userId });
  return asHandover(row);
}

export async function getPendingOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  const row = pendingRow(orgId);
  return row && row.expiresAt > toIsoTimestamp(new Date()) ? asHandover(row) : null;
}

function actionable(orgId: OrgId, actor: Actor) {
  const row = pendingRow(orgId);
  if (!row || row.toUserId !== actor.userId) throw new OwnershipHandoverError("nothing_pending");
  if (row.expiresAt <= toIsoTimestamp(new Date())) throw new OwnershipHandoverError("expired");
  return row;
}

export async function declineOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const row = actionable(orgId, actor);
  return asHandover(getDb().update(ownershipHandovers).set({ status: "declined", resolvedAt: toIsoTimestamp(new Date()) }).where(eq(ownershipHandovers.id, row.id)).returning().get());
}

export async function cancelOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  await assertRecordedOwner(actor, orgId);
  const row = pendingRow(orgId);
  if (!row || row.expiresAt <= toIsoTimestamp(new Date()) || row.fromUserId !== actor.userId) throw new OwnershipHandoverError("nothing_pending");
  return asHandover(getDb().update(ownershipHandovers).set({ status: "canceled", resolvedAt: toIsoTimestamp(new Date()) }).where(eq(ownershipHandovers.id, row.id)).returning().get());
}

export async function acceptOwnershipHandover(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const row = actionable(orgId, actor);
  const from = requireFound(await memberRepo.findMember(orgId, row.fromUserId as UserId), "Member", row.fromUserId);
  const to = requireFound(await memberRepo.findMember(orgId, actor.userId), "Member", actor.userId);
  if (from.status !== "active" || to.status !== "active") throw new OwnershipHandoverError("nothing_pending");
  const now = toIsoTimestamp(new Date());
  getDb().transaction((tx) => {
    if (to.role !== "owner") tx.update(members).set({ role: "owner", updatedAt: now }).where(and(eq(members.orgId, orgId), eq(members.id, to.id))).run();
    tx.update(organizations).set({ ownerId: actor.userId, updatedAt: now }).where(eq(organizations.id, orgId)).run();
    if (from.role === "owner") tx.update(members).set({ role: "admin", updatedAt: now }).where(and(eq(members.orgId, orgId), eq(members.id, from.id))).run();
    tx.update(ownershipHandovers).set({ status: "accepted", resolvedAt: now }).where(eq(ownershipHandovers.id, row.id)).run();
  });
  if (to.role !== "owner") await emit("member.role_changed", { ...actorEnvelope(actor), memberId: to.id, from: to.role, to: "owner" });
  if (from.role === "owner") await emit("member.role_changed", { ...actorEnvelope(actor), memberId: from.id, from: "owner", to: "admin" });
  await emit("organization.ownership_transferred", { ...actorEnvelope(actor), fromUserId: from.userId, toUserId: to.userId });
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}
