  return asHandover(getDb().update(ownershipHandovers).set({ status: "declined", resolvedAt: toIsoTimestamp(new Date()) }).where(eq(ownershipHandovers.id, row.id)).returning().get());
}

export async function cancelOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  await assertRecordedOwner(actor, orgId);
  const row = pendingRow(orgId);
  if (!row || row.expiresAt <= toIsoTimestamp(new Date()) || row.fromUserId !== actor.userId) throw new OwnershipHandoverError("nothing_pending");
  return asHandover(getDb().update(ownershipHandovers).set({ status: "canceled", resolvedAt: toIsoTimestamp(new Date()) }).where(eq(ownershipHandovers.id, row.id)).returning().get());
}

export async function acceptOwnershipHandover(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const row = actionable(orgId, actor);
  const from = requireFound(await memberRepo.findMember(orgId, row.fromUserId as UserId), "Member", row.fromUserId);
  const to = requireFound(await memberRepo.findMember(orgId, actor.userId), "Member", actor.userId);
  if (from.status !== "active" || to.status !== "active") throw new OwnershipHandoverError("nothing_pending");
  const now = toIsoTimestamp(new Date());
  getDb().transaction((tx) => {
    if (to.role !== "owner") tx.update(members).set({ role: "owner", updatedAt: now }).where(and(eq(members.orgId, orgId), eq(members.id, to.id))).run();
    tx.update(organizations).set({ ownerId: actor.userId, updatedAt: now }).where(eq(organizations.id, orgId)).run();
    if (from.role === "owner") tx.update(members).set({ role: "admin", updatedAt: now }).where(and(eq(members.orgId, orgId), eq(members.id, from.id))).run();
    tx.update(ownershipHandovers).set({ status: "accepted", resolvedAt: now }).where(eq(ownershipHandovers.id, row.id)).run();
  });
  if (to.role !== "owner") await emit("member.role_changed", { ...actorEnvelope(actor), memberId: to.id, from: to.role, to: "owner" });
  if (from.role === "owner") await emit("member.role_changed", { ...actorEnvelope(actor), memberId: from.id, from: "owner", to: "admin" });
  await emit("organization.ownership_transferred", { ...actorEnvelope(actor), fromUserId: from.userId, toUserId: to.userId });
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}
